function ensure_page_default_blocks(PDO $pdo, string $pageSlug): void {
    $all = get_all_page_default_blocks();
    if (!isset($all[$pageSlug])) return;
    
    $stmt = $pdo->prepare("SELECT id FROM pages WHERE slug = ? LIMIT 1");
    $stmt->execute([$pageSlug]);
    $page = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$page) return;
    $pageId = (int)$page['id'];
    
    $checkStmt = $pdo->prepare("SELECT id FROM content_blocks WHERE page_id = ? AND block_key = ? LIMIT 1");
    $insStmt = $pdo->prepare("INSERT INTO content_blocks (page_id, block_key, block_type, content, sort_order) VALUES (?, ?, ?, ?, ?)");
    
    // Auto-migrate legacy trust_3_text if it still holds previous WHO-GMP text
    if ($pageSlug === 'home') {
        $pdo->prepare("UPDATE content_blocks SET content = 'Strict Line Clearance & QA' WHERE page_id = ? AND block_key = 'trust_3_text' AND content = 'WHO-GMP Manufacturing Standards'")->execute([$pageId]);
    }

    foreach ($all[$pageSlug] as [$key, $type, $content, $sort]) {
        $checkStmt->execute([$pageId, $key]);
        if (!$checkStmt->fetch()) {
            $insStmt->execute([$pageId, $key, $type, $content, $sort]);
        }
    }
}

function restore_page_default_blocks(PDO $pdo, string $pageSlug): int {
    $all = get_all_page_default_blocks();
    if (!isset($all[$pageSlug])) return 0;
    
    $stmt = $pdo->prepare("SELECT id FROM pages WHERE slug = ? LIMIT 1");
    $stmt->execute([$pageSlug]);
    $page = $stmt->fetch(PDO::FETCH_ASSOC);
    if (!$page) return 0;
    $pageId = (int)$page['id'];
    
    $saveStmt = $pdo->prepare("
        INSERT INTO content_blocks (page_id, block_key, block_type, content, sort_order)
        VALUES (?, ?, ?, ?, ?)
        ON DUPLICATE KEY UPDATE block_type = VALUES(block_type),
                                content    = VALUES(content),
                                sort_order = VALUES(sort_order)
    ");
    
    $count = 0;
    foreach ($all[$pageSlug] as [$key, $type, $content, $sort]) {
        $saveStmt->execute([$pageId, $key, $type, $content, $sort]);
        $count++;
    }
    return $count;
}


